import{_ as a,c as t,o as r,aj as s}from"./chunks/framework.CDhdelVI.js";const f=JSON.parse('{"title":"Yeast","description":"","frontmatter":{"title":"Yeast"},"headers":[],"relativePath":"ingredients/yeast.md","filePath":"ingredients/yeast.md"}'),i={name:"ingredients/yeast.md"};function l(n,e,o,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="yeast" tabindex="-1">Yeast <a class="header-anchor" href="#yeast" aria-label="Permalink to “Yeast”">​</a></h1><p>Yeast is the engine in the dough: it makes gas, builds pressure, and drives fermentation flavor. Different yeast types behave differently, but each one can produce excellent bread when handled correctly.</p><h2 id="types-of-yeast" tabindex="-1">Types of Yeast <a class="header-anchor" href="#types-of-yeast" aria-label="Permalink to “Types of Yeast”">​</a></h2><h3 id="instant-yeast" tabindex="-1"><strong>Instant Yeast</strong> <a class="header-anchor" href="#instant-yeast" aria-label="Permalink to “Instant Yeast”">​</a></h3><ul><li>Can be mixed directly into flour</li><li>Strong, reliable</li><li>Smaller granules</li></ul><h3 id="active-dry-yeast" tabindex="-1"><strong>Active Dry Yeast</strong> <a class="header-anchor" href="#active-dry-yeast" aria-label="Permalink to “Active Dry Yeast”">​</a></h3><ul><li>Larger granules</li><li>Must be hydrated before use</li><li>Hydrate in water for <strong>10 minutes</strong> before mixing</li></ul><h3 id="fresh-yeast-cake-yeast" tabindex="-1"><strong>Fresh Yeast (Cake Yeast)</strong> <a class="header-anchor" href="#fresh-yeast-cake-yeast" aria-label="Permalink to “Fresh Yeast (Cake Yeast)”">​</a></h3><ul><li>70% water content (soft and crumbly)</li><li>More perishable</li><li>Calculator automatically adjusts hydration when using it</li></ul><hr><h2 id="calculator-yeast-hydration-helper" tabindex="-1">Calculator Yeast Hydration Helper <a class="header-anchor" href="#calculator-yeast-hydration-helper" aria-label="Permalink to “Calculator Yeast Hydration Helper”">​</a></h2><p>When you use a yeast type that benefits from pre-hydration, the calculator gives you two practical targets:</p><ul><li><strong>Recommended water temperature</strong> for activation</li><li><strong>Recommended water weight</strong> to hydrate the yeast</li></ul><p>And yes, this is the important part: that hydration water is automatically subtracted from your total recipe water, so your final hydration stays on target.</p><hr><h2 id="how-yeast-affects-dough" tabindex="-1">How Yeast Affects Dough <a class="header-anchor" href="#how-yeast-affects-dough" aria-label="Permalink to “How Yeast Affects Dough”">​</a></h2><h3 id="more-yeast" tabindex="-1"><strong>More Yeast</strong> <a class="header-anchor" href="#more-yeast" aria-label="Permalink to “More Yeast”">​</a></h3><ul><li>Faster fermentation</li><li>Shorter proofing window</li><li>More risk of over-proofing</li></ul><h3 id="less-yeast" tabindex="-1"><strong>Less Yeast</strong> <a class="header-anchor" href="#less-yeast" aria-label="Permalink to “Less Yeast”">​</a></h3><ul><li>Slower fermentation</li><li>Better flavor development</li><li>Better for cold-fermented doughs</li></ul><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>Store instant yeast in the fridge or freezer for long life.</li><li>When using active dry: hydrate in <strong>warm (not hot)</strong> water.</li><li>Use the calculator&#39;s yeast-water temp and weight targets so activation is consistent and hydration math stays clean.</li><li>Fresh yeast is great for delicate enriched doughs but must stay cold.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/ingredients/water.html">Water</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li></ul>',25)])])}const u=a(i,[["render",l]]);export{f as __pageData,u as default};
